from lib import *
S = SS('l29')
steps = [
    step("upstream 就是 config 里的两项:branch.main.remote = origin、branch.main.merge = refs/heads/main(远程上那个分支的完整名字)。git branch -vv 在提交说明前列出 [origin/main]——这个分支的上游是本地缓存的 origin/main。没有其它的“关系”存储,所谓追踪只是这两行配置。", t=tl(S(1)), mark=lidx(S(1), 'branch.main.remote', 'branch.main.merge'), done=lidx(S(1), '[origin/main]'), kv=KV([['branch.<名>.remote', '去哪个 remote 取'], ['branch.<名>.merge', '取远程上哪个分支'], ['git branch -vv', '显示 [上游] 与领先落后']], ['branch.<名>.merge'])),
    step("A 本地提交了 2 个,B 往远程推了 3 个提交。A 还没 fetch 时 git status -sb 只显示 [ahead 2](不知道远程多了 3 个);A 执行 git fetch 之后变成 [ahead 2, behind 3],完整的 git status 说 “Your branch and 'origin/main' have diverged, and have 2 and 3 different commits each, respectively.”,git branch -vv 里是 [origin/main: ahead 2, behind 3]。", t=tl(S(2)), mark=lidx(S(2), 'ahead 2, behind 3', 'diverged', '2 and 3 different'), done=lidx(S(2), '[ahead 2]', 'git fetch'), b=bars([['fetch 前:领先', 2, '2'], ['fetch 前:落后', 0, '0(还不知道)'], ['fetch 后:领先', 2, '2'], ['fetch 后:落后', 3, '3']], 3, mark=[3], done=[0, 1, 2]), kv=KV([['ahead', '本地有、上游没有的提交数'], ['behind', '上游有、本地没有的提交数'], ['diverged', '两个数都不为 0']], ['diverged'])),
    step("数字怎么算:领先的是 git log origin/main..main(A 本地 2、A 本地 1,共 2 个),落后的是 git log main..origin/main(B 远程 3、2、1,共 3 个)。git rev-list --left-right --count main...origin/main 输出 2 和 3,左边是只在 main 里的,右边是只在 origin/main 里的;它们的 merge-base 是提交 m1。写法 origin/main..main、^origin/main main、main --not origin/main 数出来都是 2,main..origin/main 是 3。", t=tl(S(3)), mark=lidx(S(3), '2\t3', 'merge-base', 'm1'), done=lidx(S(3), 'A 本地 2', 'B 远程 3', '领先的提交', '落后的提交'), kv=KV([['领先', 'git rev-list --count upstream..branch'], ['落后', 'git rev-list --count branch..upstream'], ['--left-right --count', '一次给出两个数'], ['边界', '两边的 merge-base']], ['领先'])),
    step("@{upstream}(简写 @{u})解出当前分支的上游 origin/main,main@{u} 同理;@{push} 是 git push 会推到的 ref。默认两者都是 origin/main。加一个叫 fork 的 remote 并设置 remote.pushDefault = fork:@{push} 在 push.default=simple 时报错 fatal: cannot resolve 'simple' push to a single destination(simple 要求推送的 remote 与上游的 remote 相同);换成 push.default=current 之后 @{push} 解成 fork/main,而 @{u} 仍是 origin/main。改用 branch.main.pushRemote = fork 同样得到 fork/main。拉取的来源和推送的去向可以是两个不同的 remote。", t=tl(S(4)), mark=lidx(S(4), 'fork/main', 'push.default=current', '@{u} 不受影响'), done=lidx(S(4), 'origin/main', 'git config --unset remote.pushDefault'), kv=KV([['@{u}', '上游:fetch / pull 的来源'], ['@{push}', 'git push 的去向'], ['simple', '要求推送的 remote 与上游相同'], ['pushDefault / pushRemote', '改变推送的 remote']], ['@{push}'])),
    step("新建分支什么时候自动设置 upstream:git switch -c plain(起点是当前分支)没有;git switch -c from-main main(起点是本地分支)也没有;git switch -c topic origin/topic(起点是 remote-tracking 分支)有——branch.topic.remote = origin、branch.topic.merge = refs/heads/topic。git push -u origin plain 推完之后写入 plain 的 remote 与 merge;git branch --set-upstream-to=origin/main 给 from-main 设置后,from-main@{u} 是 origin/main。branch.autoSetupMerge 未设置,默认 true:只有起点是 remote-tracking 分支才自动设置。", t=tl(S(5)), mark=lidx(S(5), '没有 upstream', 'branch.autoSetupMerge'), done=lidx(S(5), 'refs/heads/topic', 'refs/heads/plain', 'set-upstream-to', 'origin/main'), kv=KV([['起点是 origin/x', '自动设置 upstream'], ['起点是本地分支', '不设置'], ['push -u / --set-upstream-to', '手动设置']], ['起点是 origin/x'])),
    step("远程的 topic 分支被删除、本地 git fetch --prune 之后,git branch -vv 显示 [origin/topic: gone],git status 说 “Your branch is based on 'origin/topic', but the upstream is gone.”并提示 git branch --unset-upstream。branch.topic.* 配置还在,但 origin/topic 已经不存在了——gone 就是这个意思。", t=tl(S(6)), mark=lidx(S(6), 'gone', 'upstream is gone'), done=lidx(S(6), 'git switch -q topic', 'On branch topic'), kv=KV([['gone', '配置还在,上游分支已被删除'], ['出现条件', 'fetch --prune 之后'], ['处理', 'git branch --unset-upstream 或删掉本地分支']], ['gone'])),
]
A = mkarti('l29', 29, 'Git,upstream,ahead,behind,rev-list,真实验证,动画演示',
    '用同一个远程的两个克隆验证 upstream 与 ahead/behind:upstream 只是 branch.<名>.remote 和 .merge 两项配置;领先 = origin/main..main 的提交数,落后 = main..origin/main,git rev-list --left-right --count 一次给出两个数;@{u} 与 @{push} 可以指向不同的 remote(simple 下会报错);只有起点是 remote-tracking 分支才自动设置 upstream;远程分支删除后变成 gone。',
    'git status 里的 “ahead 2, behind 3” 是怎么算出来的?upstream 到底存在哪里?@{u} 和 @{push} 有什么不同?这篇造出一个分叉的场景,把这些全部拆开验证。',
    [('2 和 3', '领先 2、落后 3 的分叉:git rev-list --left-right --count main...origin/main 输出 2 3'), ('2 项配置', 'upstream 就是 branch.<名>.remote 和 branch.<名>.merge'), ('gone', '远程分支被删并 fetch --prune 之后,git branch -vv 显示 [origin/topic: gone]')],
    [('upstream 是什么', '<p>分支的上游只是 config 里的两项:<code>branch.&lt;名&gt;.remote</code> 和 <code>branch.&lt;名&gt;.merge</code>。<code>git branch -vv</code> 把对应的本地缓存 <code>origin/main</code> 和领先落后数显示出来。</p>'),
     ('领先与落后', '<p>ahead = 本地分支有而上游没有的提交数(<code>upstream..branch</code>),behind = 上游有而本地没有的提交数(<code>branch..upstream</code>)。两个数都不是 0 就是 diverged。</p>'),
     ('只和缓存比', '<p>数字用的是本地缓存的 <code>origin/main</code>,所以在 fetch 之前看不到远程新增的提交。</p>'),
     ('一次数两个', '<p><code>git rev-list --left-right --count main...origin/main</code> 给出 左边独有、右边独有 两个数;<code>origin/main..main</code>、<code>^origin/main main</code>、<code>main --not origin/main</code> 是等价的写法。</p>'),
     ('@{u} 与 @{push}', '<p><code>@{u}</code> 是 fetch / pull 的来源,<code>@{push}</code> 是 push 的去向,可以不同(例如 fork 工作流里从 origin 拉、往 fork 推)。<code>push.default=simple</code> 要求二者在同一个 remote,否则 <code>@{push}</code> 解析失败。</p>'),
     ('自动设置', '<p>只有新分支的起点是 remote-tracking 分支(<code>git switch -c topic origin/topic</code>)才会自动设置 upstream(<code>branch.autoSetupMerge</code> 默认 true);其它情况要 <code>push -u</code> 或 <code>--set-upstream-to</code>。上游被删之后显示 <code>gone</code>。</p>')],
    steps,
    [ENV_I_GIT + '。A、B 是同一个本机裸仓库的两个克隆;输出里的 hash 做了替换;@{push} 那一节里 fatal 行因标准错误排在输出末尾而出现在命令之后(它属于该节第一个 @{push})',
     '没有验证:branch.autoSetupMerge 的 always / simple / inherit 取值;--track=inherit;ahead/behind 在 shallow clone 或 partial clone 下的计算;status.aheadBehind=false(跳过计算);推送时 push.autoSetupRemote'],
    'upstream 与 ahead/behind')
